using MaximumSquareAreaBRFFF;
using System.Text;
using Solution = MaximumSquareAreaBRFFF.Solution3;

namespace MaximumSquareAreaBRFFFTest;

[TestClass]
public sealed class Test1
{
    [TestMethod]
    public void TestMethod1()
    {
        Solution solution = new Solution();
        var result = solution.MaximizeSquareArea(4, 3, [2, 3], [2]);
        Assert.AreEqual(4, result);
    }

    [TestMethod]
    public void TestMethod2()
    {
        Solution solution = new Solution();
        var result = solution.MaximizeSquareArea(6, 7, [2], [4]);
        Assert.AreEqual(-1, result);
    }

    [TestMethod]
    public void TestMethod3()
    {
        Solution solution = new Solution();
        var result = solution.MaximizeSquareArea(10,10, [3,4,6] , [2,3,6]);
        Assert.AreEqual(81, result);
    }

    [TestMethod]
    public void TestMethod4()
    {
        Solution solution = new Solution();
        var result = solution.MaximizeSquareArea(10, 11, [3, 4, 6], [2, 3, 6]);
        Assert.AreEqual(81, result);
    }

    [TestMethod]
    public void TestMethod5()
    {
        Solution solution = new Solution();
        var result = solution.MaximizeSquareArea(10, 30, [3, 4, 6], [2, 3, 6]);
        Assert.AreEqual(25, result);
    }

    [TestMethod]
    public void TestMethod6()
    {
        Solution solution = new Solution();
        var result = solution.MaximizeSquareArea(1000_000_000, 1000_000_000
            , Enumerable.Range(1000_000_000 - 600, 600).ToArray()
            , Enumerable.Range(1000_000_000 - 600, 600).ToArray());
        Assert.AreEqual(64, result);
    }

    [TestMethod]
    public void TestMethod7()
    {
        Solution solution = new Solution();
        var result = solution.MaximizeSquareArea(
            6,4
            , [3]
            , [3,2]);
        Assert.AreEqual(9, result);
    }

    [TestMethod]
    public void TestMethod8()
    {
        Solution solution = new Solution();
        var result = solution.MaximizeSquareArea(
            9, 7
            , [6, 4, 7, 5, 8]
            , [6, 4, 2, 3]);
        Assert.AreEqual(36, result);
    }

    [TestMethod]
    public void TestMethod9()
    {
        Solution solution = new Solution();
        var result = solution.MaximizeSquareArea(
            9, 7
            , [4, 5, 6, 7, 8]
            , [2, 3, 4, 6]);
        Assert.AreEqual(36, result);
    }

